#!/bin/zsh
# Slice 1's full case set (registration-slice-1.md section 2, amendment 1): the same Swift tests as the gate, pointed at
# .build/pins-full (every case of macTEM's harnesses and every angle plant, regenerated by tools/slice-1/pins.py) through
# IMAGOKIT_PINS_FULL. Run at every frozen commit and logged in docs/status.md; not part of CI (it needs the oracle venv and
# macTEM beside this repository to regenerate the pins).
#
#   ../tools/memcap.sh -- References/oracle-venv/bin/python -I -B tools/slice-1/pins.py   # when .build/pins-full is missing
#   tools/slice-1/full-parity.sh
set -euo pipefail
cd "${0:A:h}/../.."
[[ -f .build/pins-full/fft/ref/manifest.json && -f .build/pins-full/spot/ref/manifest.json && -f .build/pins-full/angle/manifest.json ]] \
  || { print -u2 "full-parity: .build/pins-full is missing; run tools/slice-1/pins.py first"; exit 1 }
IMAGOKIT_PINS_FULL=$PWD/.build/pins-full swift test -c release --filter ImagoFFTTests
